65	static int neon_rot_ldr_at_top_rowmajor_sve_init(struct test *test) {
66	#if defined(__aarch64__)
67	    unsigned long hwcap = getauxval(AT_HWCAP);
68	    if ((hwcap & HWCAP_SVE) == 0) {
69	        log_skip(CpuNotSupportedSkipCategory,
70	                 "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_rowmajor_sve");
71	        return EXIT_SKIP;
72	    }
73	
74	    const int lanes = (int)svcntd();
75	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS * lanes;
76	
77	    auto *data = static_cast<NeonRotLdrAtTopRowMajorSveData *>(malloc(sizeof(NeonRotLdrAtTopRowMajorSveData)));
78	    data->lanes = lanes;
79	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
80	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
81	    data->scratch = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
82	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
83	
84	    memset_random(data->srcA, elems * sizeof(uint64_t));
85	    memset_random(data->srcB, elems * sizeof(uint64_t));
86	    memset_random(data->scratch, elems * sizeof(uint64_t));
87	
88	    /* golden: same rotating composition per slot (slot%4, whole vector), computed on the same SVE units */
89	    svbool_t pg = svptrue_b64();
90	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS; i++) {
91	        svuint64_t a = svld1_u64(pg, data->srcA + (size_t)i * lanes);
92	        svuint64_t b = svld1_u64(pg, data->srcB + (size_t)i * lanes);
93	        svuint64_t res;
94	        switch (i % 4) {
95	            case 0: res = svadd_u64_x(pg, a, b); break;
96	            case 1: res = sveor_u64_x(pg, a, b); break;
97	            case 2: res = svand_u64_x(pg, a, b); break;
98	            case 3: res = svorr_u64_x(pg, a, b); break;
99	        }
100	        svst1_u64(pg, data->expected + (size_t)i * lanes, res);
101	    }
102	
103	    test->data = data;
104	    return EXIT_SUCCESS;
105	#else
106	    (void)test;
107	    log_skip(CpuNotSupportedSkipCategory,
108	             "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_rowmajor_sve");
109	    return EXIT_SKIP;
110	#endif
111	}
