123	        report_fail_msg("neon_rot_ldr_at_top_rowmajor_sve: vector length changed between init and run");
124	    }
125	
126	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS * data->lanes;
127	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
128	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
129	
130	    uint64_t sweep = 0;
131	    TEST_LOOP(test, 1 << 13) {
132	        const bool ascending = (sweep & 1) == 0;
133	        for (int n = 0; n < NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS; n++) {
134	            const int i = ascending ? n : (NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS - 1 - n);
135	            const size_t off = (size_t)i * data->lanes;
136	
137	            /* 3rd load at the TOP of the iteration (before the sources);
138	             * value intentionally discarded — this probe measures the
139	             * presence/position of the load, not its data */
140	            svuint64_t unused_x = load_vec_sve(data->scratch + off);
141	            (void)unused_x;
142	
143	            svuint64_t a = load_vec_sve(data->srcA + off);
144	            svuint64_t b = load_vec_sve(data->srcB + off);
145	            svuint64_t res;
146	
147	            switch (i % 4) {
148	                case 0: res = svadd_u64_x(svptrue_b64(), a, b); break;
149	                case 1: res = sveor_u64_x(svptrue_b64(), a, b); break;
150	                case 2: res = svand_u64_x(svptrue_b64(), a, b); break;
151	                case 3: res = svorr_u64_x(svptrue_b64(), a, b); break;
152	            }
153	
154	            /* both stores write the ALU result — the str temp / str dst
155	             * pair stays back-to-back with NO memory op in between */
156	            store_vec_sve(temp + off, res);
157	            store_vec_sve(dst + off, res);
158	        }
159	        sweep++;
160	
161	        if (memcmp(dst, data->expected, elems * sizeof(uint64_t)) != 0) {
162	            /* cold path: locate mismatches, record bit-level evidence (golden/actual/xor) */
163	            {
164	                size_t _dump_bad = 0;
165	                int _dump_shown = 0;
166	                for (size_t _dump_j = 0; _dump_j < elems; ++_dump_j) {
167	                    if (dst[_dump_j] != data->expected[_dump_j]) {
168	                        ++_dump_bad;
169	                        if (_dump_shown < 8) {
170	                            log_error("neon_rot_ldr_at_top_rowmajor_sve: mismatch at flat=%zu slot=%zu lane=%zu: golden=0x%016llx actual=0x%016llx xor=0x%016llx",
171	                                      _dump_j, _dump_j / (size_t)data->lanes, _dump_j % (size_t)data->lanes,
172	                                      (unsigned long long)data->expected[_dump_j],
173	                                      (unsigned long long)dst[_dump_j],
174	                                      (unsigned long long)(data->expected[_dump_j] ^ dst[_dump_j]));
175	                            ++_dump_shown;
176	                        }
177	                    }
178	                }
179	                log_error("neon_rot_ldr_at_top_rowmajor_sve: total mismatched elements: %zu / %zu (slots x lanes)",
180	                          _dump_bad, elems);
181	            }
182	            report_fail_msg("neon_rot_ldr_at_top_rowmajor_sve data miscompare");
183	        }
184	    }
185	
186	    free(dst);
187	    free(temp);
188	    return EXIT_SUCCESS;
189	}
