1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b neon_rot_ldr_at_top_mla_sve
7	 * @parblock
8	 * SVE port of neon_rot_ldr_at_top_mla (source:
9	 * missing_testcases_20261009/tests/cpu/misc/neon_rot_ldr_at_top_mla.cpp).
10	 *
11	 * Algebraic variant of the position probe (original-parent lineage,
12	 * forward-only sweep): the rotation runs in 32-bit lanes —
13	 * mul / mla-style (a + a*b) / mls-style (b - a*b) / eor (control) —
14	 * probing the MAC pipe + accumulate chains instead of 2-input logic/add
15	 * ops. Sources are narrowed to 15-bit magnitude (& 0xFFFF) and
16	 * PERSISTED back to the source buffers in init so run-side recomputation
17	 * sees identical inputs and s32 products never overflow (original
18	 * semantics). Same slot geometry otherwise: dead 3rd ldr z (scratch) at
19	 * top + 2 source loads + back-to-back store pair, 1024 slots of
20	 * svcntw() u32 lanes.
21	 *
22	 * Instruction note: the original composes mla/mls explicitly as
23	 * add(mul)/sub(mul) (NEON has no u32 mla); the SVE port composes the
24	 * same way (svadd(svmul)/svsub(svmul)) so the instruction structure
25	 * matches the original datapath.
26	 * @endparblock
27	 */
28	
29	#include "sandstone.h"
30	#include <cstdint>
31	#include <cstring>
32	#include <cstdlib>
33	
34	#if defined(__aarch64__)
35	#include <arm_sve.h>
36	#include <sys/auxv.h>
37	
38	#ifndef HWCAP_SVE
39	#define HWCAP_SVE (1 << 22)
40	#endif
41	#endif
42	
43	#define NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS 1024
44	
45	struct NeonRotLdrAtTopMlaSveData {
46	    uint32_t *srcA;
47	    uint32_t *srcB;
48	    uint32_t *scratch;
49	    uint32_t *expected;
50	    int lanes;
51	};
52	
53	#if defined(__aarch64__)
54	
55	static inline void store_vec_sve(void *addr, svuint32_t val) {
56	    svst1_u32(svptrue_b32(), static_cast<uint32_t *>(addr), val);
57	}
58	
59	static inline svuint32_t load_vec_sve(const void *addr) {
60	    svuint32_t res;
61	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
62	    return res;
63	}
64	
65	#endif
66	
67	static int neon_rot_ldr_at_top_mla_sve_init(struct test *test) {
68	#if defined(__aarch64__)
69	    unsigned long hwcap = getauxval(AT_HWCAP);
70	    if ((hwcap & HWCAP_SVE) == 0) {
71	        log_skip(CpuNotSupportedSkipCategory,
72	                 "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_mla_sve");
73	        return EXIT_SKIP;
74	    }
75	
76	    const int lanes = (int)svcntw();
77	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS * lanes;
78	
79	    auto *data = static_cast<NeonRotLdrAtTopMlaSveData *>(malloc(sizeof(NeonRotLdrAtTopMlaSveData)));
80	    data->lanes = lanes;
81	    data->srcA = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
82	    data->srcB = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
83	    data->scratch = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
84	    data->expected = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
85	
86	    memset_random(data->srcA, elems * sizeof(uint32_t));
87	    memset_random(data->srcB, elems * sizeof(uint32_t));
88	    memset_random(data->scratch, elems * sizeof(uint32_t));
89	
90	    /* 收窄持久化 + golden: mul / mla式(a+a*b) / mls式(b-a*b) / eor, 同 SVE 单元 */
91	    svbool_t pg = svptrue_b32();
92	    svuint32_t vmask = svdup_u32(0x0000ffffu);
93	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS; i++) {
94	        const size_t off = (size_t)i * lanes;
95	        svuint32_t a = svand_u32_x(pg, svld1_u32(pg, data->srcA + off), vmask);
96	        svuint32_t b = svand_u32_x(pg, svld1_u32(pg, data->srcB + off), vmask);
97	        svst1_u32(pg, data->srcA + off, a);   /* persist narrowed sources */
98	        svst1_u32(pg, data->srcB + off, b);
99	        svint32_t sa = svreinterpret_s32_u32(a);
100	        svint32_t sb = svreinterpret_s32_u32(b);
101	        svuint32_t res;
102	        switch (i % 4) {
103	            case 0: res = svreinterpret_u32_s32(svmul_s32_x(pg, sa, sb)); break;
104	            case 1: res = svreinterpret_u32_s32(svadd_s32_x(pg, svmul_s32_x(pg, sa, sb), sa)); break;
105	            case 2: res = svreinterpret_u32_s32(svsub_s32_x(pg, svmul_s32_x(pg, sa, sb), sb)); break;
106	            case 3: res = sveor_u32_x(pg, a, b); break;
107	        }
108	        svst1_u32(pg, data->expected + off, res);
109	    }
110	
111	    test->data = data;
112	    return EXIT_SUCCESS;
113	#else
114	    (void)test;
115	    log_skip(CpuNotSupportedSkipCategory,
116	             "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_mla_sve");
117	    return EXIT_SKIP;
118	#endif
119	}
120	
121	#if defined(__aarch64__)
122	static int neon_rot_ldr_at_top_mla_sve_run(struct test *test, int cpu) {
123	    (void)cpu;
124	    auto *data = static_cast<NeonRotLdrAtTopMlaSveData *>(test->data);
125	
126	    if ((int)svcntw() != data->lanes) {
127	        log_error("neon_rot_ldr_at_top_mla_sve: vector length changed between init (%d) and run (%d)",
128	                  data->lanes, (int)svcntw());
129	        report_fail_msg("neon_rot_ldr_at_top_mla_sve: vector length changed between init and run");
130	    }
131	
132	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS * data->lanes;
133	    uint32_t *temp = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
134	    uint32_t *dst  = static_cast<uint32_t *>(aligned_alloc(64, elems * sizeof(uint32_t)));
135	
136	    TEST_LOOP(test, 1 << 13) {
137	        for (int i = 0; i < NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS; i++) {
138	            const size_t off = (size_t)i * data->lanes;
139	
140	            svuint32_t unused_x = load_vec_sve(data->scratch + off);
141	            (void)unused_x;
142	
143	            svuint32_t a = load_vec_sve(data->srcA + off);
144	            svuint32_t b = load_vec_sve(data->srcB + off);
145	            svint32_t sa = svreinterpret_s32_u32(a);
146	            svint32_t sb = svreinterpret_s32_u32(b);
147	            svuint32_t res;
148	
149	            switch (i % 4) {
150	                case 0: res = svreinterpret_u32_s32(svmul_s32_x(svptrue_b32(), sa, sb)); break;
151	                case 1: res = svreinterpret_u32_s32(svadd_s32_x(svptrue_b32(), svmul_s32_x(svptrue_b32(), sa, sb), sa)); break;
152	                case 2: res = svreinterpret_u32_s32(svsub_s32_x(svptrue_b32(), svmul_s32_x(svptrue_b32(), sa, sb), sb)); break;
153	                case 3: res = sveor_u32_x(svptrue_b32(), a, b); break;
154	            }
155	
156	            store_vec_sve(temp + off, res);
157	            store_vec_sve(dst + off, res);
158	        }
159	
160	        if (memcmp(dst, data->expected, elems * sizeof(uint32_t)) != 0) {
161	            /* cold path: locate mismatches, record bit-level evidence (golden/actual/xor) */
162	            {
163	                size_t _dump_bad = 0;
164	                int _dump_shown = 0;
165	                for (size_t _dump_j = 0; _dump_j < elems; ++_dump_j) {
166	                    if (dst[_dump_j] != data->expected[_dump_j]) {
167	                        ++_dump_bad;
168	                        if (_dump_shown < 8) {
169	                            log_error("neon_rot_ldr_at_top_mla_sve: mismatch at flat=%zu slot=%zu lane=%zu: golden=0x%08x actual=0x%08x xor=0x%08x",
170	                                      _dump_j, _dump_j / (size_t)data->lanes, _dump_j % (size_t)data->lanes,
171	                                      (unsigned)data->expected[_dump_j],
172	                                      (unsigned)dst[_dump_j],
173	                                      (unsigned)(data->expected[_dump_j] ^ dst[_dump_j]));
174	                            ++_dump_shown;
175	                        }
176	                    }
177	                }
178	                log_error("neon_rot_ldr_at_top_mla_sve: total mismatched elements: %zu / %zu (slots x lanes)",
179	                          _dump_bad, elems);
180	            }
181	            report_fail_msg("neon_rot_ldr_at_top_mla_sve data miscompare");
182	        }
183	    }
184	
185	    free(dst);
186	    free(temp);
187	    return EXIT_SUCCESS;
188	}
189	#else
190	static int neon_rot_ldr_at_top_mla_sve_run(struct test *test, int cpu) {
191	    (void)test; (void)cpu;
192	    log_skip(CpuNotSupportedSkipCategory,
193	             "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_mla_sve");
194	    return EXIT_SKIP;
195	}
196	#endif
197	
198	static int neon_rot_ldr_at_top_mla_sve_cleanup(struct test *test) {
199	    auto *data = static_cast<NeonRotLdrAtTopMlaSveData *>(test->data);
200	    if (data) {
201	        free(data->srcA);
202	        free(data->srcB);
203	        free(data->scratch);
204	        free(data->expected);
205	        free(data);
206	    }
207	    return EXIT_SUCCESS;
208	}
209	
210	DECLARE_TEST(neon_rot_ldr_at_top_mla_sve,
211	             "SVE algebraic variant of the position probe: rotation mul/mla-style/mls-style/eor "
212	             "in 32-bit lanes (MAC pipe + accumulate chain signature test) at forward-only sweep "
