#include <cstdint>
#include <cstring>
#include <cstdlib>

#if defined(__aarch64__)
#include <arm_sve.h>
#include <sys/auxv.h>

#ifndef HWCAP_SVE
#define HWCAP_SVE (1 << 22)
#endif
#endif

#define NEON_ROT_LDR_AT_TOP_MLA_SVE_SLOTS 1024

struct NeonRotLdrAtTopMlaSveData {
    uint32_t *srcA;
    uint32_t *srcB;
    uint32_t *scratch;
    uint32_t *expected;
    int lanes;
};

