5	 *
6	 * @test @b mite_sve
7	 * @parblock
8	 * SVE port of mite: the add/eor/sub constant chain and the parity/bit16
9	 * branch logic run on vector lanes (svadd/sveor/svsub + predicate selects
10	 * replacing the scalar branches), golden per the scalar reference.
11	 * @endparblock
12	 */
13	
14	#include "sandstone.h"
15	#include <cstdint>
16	#include <cstring>
17	#include <cstdlib>
18	
19	#if defined(__aarch64__)
20	#include <arm_sve.h>
21	#include <sys/auxv.h>
22	
23	#ifndef HWCAP_SVE
24	#define HWCAP_SVE (1 << 22)
25	#endif
26	#endif
27	
28	#define MITE_SVE_ITERATIONS 1024
29	
30	static constexpr uint32_t MITE_CONST1 = 0x12345678u;
31	static constexpr uint32_t MITE_CONST2 = 0x9ABCDEF0u;
32	static constexpr uint32_t MITE_CONST3 = 0x55555555u;
33	
34	struct MiteSveData {
35	    uint32_t *input;
36	    uint32_t *expected;
37	};
38	
39	/* 标量参考 (golden, 与原版 process_value 同语义) */
40	static inline uint32_t process_value_ref(uint32_t w0_val)
41	{
42	    w0_val = w0_val + MITE_CONST1;
43	    w0_val = w0_val ^ MITE_CONST2;
44	    w0_val = w0_val - MITE_CONST3;
45	    if (w0_val & 1) w0_val = w0_val * 13;
46	    else            w0_val = w0_val * 17;
47	    if ((w0_val >> 16) & 1) w0_val += 1;
48	    return w0_val;
49	}
50	
51	static int mite_sve_init(struct test *test)
52	{
53	#if defined(__aarch64__)
54	    unsigned long hwcap = getauxval(AT_HWCAP);
55	    if ((hwcap & HWCAP_SVE) == 0) {
56	        log_skip(CpuNotSupportedSkipCategory,
57	                 "to be implemented (placeholder): ARM SVE required for mite_sve");
58	        return EXIT_SKIP;
59	    }
60	#endif
61	    auto *data = (MiteSveData *)malloc(sizeof(MiteSveData));
62	    data->input = (uint32_t *)aligned_alloc_safe(64, MITE_SVE_ITERATIONS * sizeof(uint32_t));
63	    data->expected = (uint32_t *)aligned_alloc_safe(64, MITE_SVE_ITERATIONS * sizeof(uint32_t));
64	    memset_random(data->input, MITE_SVE_ITERATIONS * sizeof(uint32_t));
65	    for (int i = 0; i < MITE_SVE_ITERATIONS; ++i)
66	        data->expected[i] = process_value_ref(data->input[i]);
67	    test->data = data;
68	    return EXIT_SUCCESS;
69	}
70	
71	#if defined(__aarch64__)
72	static int mite_sve_run(struct test *test, int cpu)
73	{
74	    (void)cpu;
75	    auto *data = (MiteSveData *)test->data;
76	    uint32_t *dst = (uint32_t *)aligned_alloc(64, MITE_SVE_ITERATIONS * sizeof(uint32_t));
77	    const int lanes = svcntw();
78	
79	    TEST_LOOP(test, 1 << 13) {
